def gen(rng):
    def fmt(n, edges):
        return f"{n} {len(edges)}\n" + "\n".join(f"{a} {b}" for a, b in edges)

    def orient(a, b):
        return (a, b) if rng.random() < 0.5 else (b, a)

    def forest(n, p):
        perm = list(range(n))
        rng.shuffle(perm)
        edges = []
        for i in range(1, n):
            if rng.random() < p:
                edges.append(orient(perm[i], perm[rng.randrange(i)]))
        rng.shuffle(edges)
        return edges

    def add_extra(n, edges, k):
        have = set()
        for a, b in edges:
            have.add((min(a, b), max(a, b)))
        tries = 0
        while k > 0 and tries < 200:
            tries += 1
            a, b = rng.randrange(n), rng.randrange(n)
            if a == b or (min(a, b), max(a, b)) in have:
                continue
            have.add((min(a, b), max(a, b)))
            edges.append(orient(a, b))
            k -= 1
        return edges

    tests = [fmt(1, []), fmt(2, [(0, 1)]), fmt(3, [(0, 1), (1, 2), (2, 0)]), fmt(4, []),
             fmt(4, [(0, 1), (2, 3)]), fmt(5, [(0, 1), (1, 2), (2, 3), (3, 4), (4, 0)])]
    for _ in range(30):
        n = rng.randint(1, 9)
        edges = forest(n, rng.choice([0.6, 0.9, 1.0]))
        if rng.random() < 0.5:
            add_extra(n, edges, rng.randint(1, 2))
        tests.append(fmt(n, edges))
    for _ in range(8):
        n = rng.randint(3, 9)
        edges = []
        for a in range(n):
            for b in range(a + 1, n):
                if rng.random() < 0.18:
                    edges.append(orient(a, b))
        tests.append(fmt(n, edges))
    N = 100000
    path = [(i, i + 1) for i in range(N - 1)]
    tests.append(fmt(N, path))
    p2 = list(path)
    p2.append((0, N - 1 - rng.randint(0, 10)))
    tests.append(fmt(N, p2))
    tests.append(fmt(N, [(0, i) for i in range(1, N)]))
    tests.append(fmt(N, forest(N, 0.9)))
    rnd = set()
    while len(rnd) < N:
        a, b = rng.randrange(N), rng.randrange(N)
        if a != b:
            rnd.add((min(a, b), max(a, b)))
    tests.append(fmt(N, list(rnd)))
    tri = []
    for t in range(33333):
        a = 3 * t
        tri += [(a, a + 1), (a + 1, a + 2), (a + 2, a)]
    tests.append(fmt(99999, tri))
    return tests
